const $ = (s) => document.querySelector(s);
const champions = {
  ahri: { name:'Ahri', title:'The Nine-Tailed Fox', role:'Mid', style:'Catch & reposition', line:'Make the opening. Own the moment.', text:'An elusive mage for players who like to find an angle, pick their moment, and leave a little mystery behind.', tip:'Keep an escape route in mind before committing to a pick.', color:'#b5d9e3' },
  lux: { name:'Lux', title:'The Lady of Luminosity', role:'Mid', style:'Range & control', line:'A little light changes everything.', text:'Create space for your team with long-range pressure and a well-timed burst of light.', tip:'Play behind your frontline and look for a clear line to your target.', color:'#ebd3a2' },
  yasuo: { name:'Yasuo', title:'The Unforgiven', role:'Mid', style:'Movement & precision', line:'Find your flow. Follow the wind.', text:'A roaming swordsman for players who enjoy close combat, patient timing, and decisive movement.', tip:'Plan your way out as carefully as your way in.', color:'#b2cbbe' }
};
const units = {garen:'Garen',leona:'Leona',ahri:'Ahri',lux:'Lux',ashe:'Ashe',lulu:'Lulu',jinx:'Jinx',yasuo:'Yasuo'};
const formations = [
  {id:'starlight',name:'Starlight backline',tag:'Protect your carry',carry:'ahri',line:'A little space. A lot of magic.',text:'Keep the damage dealers out of the first clash. Give your frontline room to hold, then adjust your carry after scouting.',board:{1:'garen',3:'leona',8:'yasuo',20:'lulu',21:'ashe',24:'ahri',26:'lux'},stages:['Establish a frontline','Add a second damage source','Scout and reposition']},
  {id:'frontline',name:'Hold your ground',tag:'Build a sturdy front',carry:'garen',line:'Good things take a little time.',text:'Start with a resilient front row and build your damage behind it. Spread your backline so one threat cannot reach everyone.',board:{0:'garen',2:'leona',4:'yasuo',15:'lulu',22:'lux',25:'ashe',27:'jinx'},stages:['Make your board stable','Support your damage dealers','Spread against threats']},
  {id:'pocket',name:'Pocket fireworks',tag:'Give your carry a moment',carry:'jinx',line:'Small team. Big entrance.',text:'Keep a clear pocket for your main damage dealer. Move the supporting units around that pocket as the lobby changes.',board:{1:'leona',4:'garen',10:'yasuo',21:'lulu',23:'jinx',25:'ashe',27:'lux'},stages:['Find your damage core','Protect the back row','Adapt to the final opponent']}
];
const leagueMatches=[{id:'l1',hero:'ahri',result:'Victory',kda:'8 / 2 / 11',time:'28:42',date:'Today, 8:24 PM',line:'Patience paid off.',note:'Your strongest moments came after the first engage. Keep looking for that second opening.',cs:'186',vision:'24'}, {id:'l2',hero:'lux',result:'Defeat',kda:'4 / 5 / 13',time:'34:16',date:'Today, 7:46 PM',line:'A lesson in positioning.',note:'Before the next objective, think about where you can contribute without crossing your frontline.',cs:'204',vision:'32'}, {id:'l3',hero:'yasuo',result:'Victory',kda:'11 / 4 / 6',time:'31:08',date:'Yesterday, 9:10 PM',line:'The right opening.',note:'You found your best fights with your team nearby. Keep that connection when moving between lanes.',cs:'221',vision:'18'}];
const tftMatches=[{id:'t1',place:'1st',plan:0,date:'Today, 9:12 PM',stage:'6-5',line:'Room for one at the top.',note:'Your backline survived the final engagement. A small positioning change made room for a big finish.'},{id:'t2',place:'4th',plan:1,date:'Today, 8:30 PM',stage:'5-6',line:'A steady finish.',note:'You stabilized the board and secured a top-four finish. Review when you chose to spend your gold.'},{id:'t3',place:'7th',plan:2,date:'Yesterday, 10:05 PM',stage:'4-5',line:'A little too much patience.',note:'The board needed help sooner. Next time, weigh the health you are spending against the gold you are saving.'}];
let state={champion:'ahri',savedLeague:false,savedChampions:[],savedComps:[],boards:{},board:null,plan:0,alerts:true};
try {const saved=JSON.parse(localStorage.getItem('queuepop-worlds-v1')||'null');if(saved && typeof saved==='object') {state.champion=champions[saved.champion]?saved.champion:'ahri';state.savedChampions=Array.isArray(saved.savedChampions)?saved.savedChampions.filter(id=>champions[id]):saved.savedLeague?[state.champion]:[];state.savedComps=Array.isArray(saved.savedComps)?saved.savedComps.filter(n=>Number.isInteger(n)&&n>=0&&n<3):[];state.plan=Number.isInteger(saved.plan)&&saved.plan>=0&&saved.plan<3?saved.plan:0;state.alerts=saved.alerts!==false;state.board=saved.board&&typeof saved.board==='object'?Object.fromEntries(Object.entries(saved.board).filter(([k,v])=>/^\d+$/.test(k)&&+k<28&&units[v])):null;}}catch{}
try { const stored=JSON.parse(localStorage.getItem('queuepop-worlds-v1')||'{}'); for(let i=0;i<3;i++){const b=stored.boards?.[i];if(b&&typeof b==='object')state.boards[i]=Object.fromEntries(Object.entries(b).filter(([k,v])=>/^\d+$/.test(k)&&+k<28&&units[v]));} } catch{}
Object.defineProperty(state,'savedLeague',{get(){return state.savedChampions.includes(state.champion);},set(saved){state.savedChampions=saved?[...new Set([...state.savedChampions,state.champion])]:state.savedChampions.filter(id=>id!==state.champion);}});
let currentGame='home',currentPage='',buildStage=0,historyFilter='All',selectedUnit=null,selectedCell=null,queueDemo=false;
const persist=()=>{state.boards[state.plan]=state.board;try{localStorage.setItem('queuepop-worlds-v1',JSON.stringify(state));}catch{toast('Your browser could not save this preference.');}};
let noticeTimer;
function toast(text){$('#notice').textContent=text;$('#notice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').hidden=true,3500);}
const icon=(id,extra='')=>`<img class="unit-icon ${extra}" src="assets/${id}-icon.png" alt="">`;
const link=(href,text,cls='action')=>`<a class="${cls}" href="${href}">${text}<span aria-hidden="true">↗</span></a>`;
const saveButton=(saved,action,label)=>`<button class="action secondary" data-action="${action}" aria-pressed="${saved}">${saved?'✓ Saved':label}</button>`;
function subnav(game,page){const league=game==='league';const labels=league?[['','Overview'],['champions','Champions'],['builds','Builds'],['history','Match history']]:[['','Overview'],['comps','Team comps'],['planner','Board planner'],['history','Match history']];return `<nav class="game-nav" aria-label="${league?'League of Legends':'TFT'} navigation"><a class="game-lockup" href="#/${game}">${league?'LEAGUE <small>OF LEGENDS</small>':'TEAMFIGHT <small>TACTICS</small>'}</a><div>${labels.map(([p,t])=>`<a href="#/${game}${p?'/'+p:''}" ${page===p?'aria-current="page"':''}>${t}</a>`).join('')}</div><span class="study-label">Concept collection</span></nav>`;}
function pageHead(kicker,title,text,aside=''){return `<header class="page-title"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p>${text}</p></div>${aside}</header>`;}
function home(){return `<section class="hub-intro"><div><p class="eyebrow">Your next good game starts here</p><h1>Different worlds.<br>Same companion.</h1><p>Your champions, your plans, your next queue.<br>A place for every way you play.</p></div><div class="home-sigil" aria-hidden="true"><div></div><img src="assets/queuepop.svg" alt=""></div><a class="resume" href="#/${state.savedLeague?'league/builds':'tft/planner'}"><span class="qp-dot"></span>Pick up where you left off<strong>${state.savedLeague?champions[state.champion].name+' / saved plan':'Your next team starts with one idea.'}</strong><span>Open ${state.savedLeague?'build':'board planner'} <b>↗</b></span></a></section>
  <section class="worlds" aria-label="Choose your game"><a class="world-gate league-gate" href="#/league"><img src="assets/ahri.webp" alt="Ahri in a luminous Ionian forest"><div><span class="world-number">01 / The Rift</span><h2>LEAGUE<small>OF LEGENDS</small></h2><p>Find your champion.<br>Make your mark.</p><span class="gate-entry">Enter the Rift <b>↗</b></span></div></a><a class="world-gate tft-gate" href="#/tft"><img src="assets/tft-party.webp" alt="Little Legends gathered in a colorful magical world"><div><span class="world-number">02 / The Convergence</span><h2>TEAMFIGHT<small>TACTICS</small></h2><p>A little ingenuity.<br>A whole lot of possibility.</p><span class="gate-entry">Take your seat <b>↗</b></span></div></a><a class="world-gate deadlock-gate" href="deadlock.html#/"><img src="../deadlock/assets/city.webp" alt="Deadlock's haunted New York skyline"><div><span class="world-number">03 / The city</span><h2>DEADLOCK</h2><p>Good company.<br>Bad intentions.</p><span class="gate-entry">Answer the call <b>↗</b></span></div></a></section>
  <section class="hub-bottom"><div><span class="little-sigil">✦</span><div><h3>Go live a little.</h3><p>Your queue companion belongs with you, whichever world you’re in.</p></div></div>${link('#/companion','Meet your companion','text-link')}</section>`;}
function championButtons(){return Object.entries(champions).map(([id,c])=>`<button class="champ-choice ${state.champion===id?'selected':''}" data-champion="${id}" aria-pressed="${state.champion===id}">${icon(id)}<span>${c.name}<small>${c.style}</small></span><i>${state.champion===id?'◆':'◇'}</i></button>`).join('');}
function leagueOverview(){const c=champions[state.champion];return `${subnav('league','')}<section class="league-hero" style="--champ-art:url('assets/${state.champion}.webp')"><div class="hero-inlay" aria-hidden="true"></div><div class="league-copy"><p class="eyebrow">Welcome to Summoner’s Rift</p><h1>Every legend<br>starts somewhere.</h1><p>Find a champion that feels like you.<br>Bring a plan worth playing.</p>${link('#/league/champions','Find your champion')}<div class="hero-signature"><span>Featuring</span><strong>${c.name}</strong><small>${c.title}</small></div></div><div class="hero-selector" aria-label="Featured champion">${championButtons()}</div><span class="scene-coordinate" aria-hidden="true">RUNETERRA / IONIA</span></section><section class="league-after"><article class="next-plan"><span class="roman">I</span><div><p class="eyebrow">Before the next queue</p><h2>A little intention.<br>A better first move.</h2><p>Your champion, your approach, and a clear starting point.</p>${link('#/league/builds','Prepare your loadout','text-link')}</div></article><a class="last-match" href="#/league/history/l1"><span class="eyebrow">Last match / Sample</span><div>${icon('ahri')}<div><span class="result-win">Victory</span><h3>Ahri</h3></div><b>8 / 2 / 11</b></div><p>Patience paid off. <span>Review match ↗</span></p></a></section>`;}
function leagueChampions(){const c=champions[state.champion];return `${subnav('league','champions')}${pageHead('The champion collection','Find your kind of legend.','Three champions to explore in this concept.')}<section class="champion-studio"><aside class="champ-directory"><p class="eyebrow">Your mid-lane collection</p>${championButtons()}<p class="aside-note">The right champion is more than a win rate.</p></aside><article class="champ-dossier" style="--champ-art:url('assets/${state.champion}.webp')"><div class="champ-dossier-copy"><p class="eyebrow">${c.title}</p><h2>${c.name}</h2><span class="role-badge">${c.role} / ${c.style}</span><p>${c.text}</p>${link('#/league/builds','Explore this champion’s plan')}</div></article></section><section class="quiet-note"><span>◇</span><div><h3>${c.line}</h3><p>${c.tip}</p></div></section>`;}
const itemSets=[[
 ['1056','Doran’s Ring','A starting point for your lane.'],['2003','Health Potion','A little room to recover.'],['3340','Stealth Ward','Keep an eye on your approach.']
],[['3020','Sorcerer’s Shoes','Make room to move.'],['3108','Fiendish Codex','Build toward your next purchase.'],['1058','Needlessly Large Rod','Invest in your damage.']],[['3089','Rabadon’s Deathcap','Commit to your damage.'],['3157','Zhonya’s Hourglass','Consider a defensive answer.'],['3135','Void Staff','Adapt to your opponent’s defenses.']]];
const swordSets=[[['1055','Doran’s Blade','A starting point for your lane.'],['2003','Health Potion','A little room to recover.'],['3340','Stealth Ward','Watch the approach.']],[['3006','Berserker’s Greaves','Find your tempo.'],['1043','Recurve Bow','Work toward your core.'],['1038','B. F. Sword','Invest in damage.']],[['3031','Infinity Edge','Commit to your damage.'],['3072','Bloodthirster','Consider a sustain option.'],['3026','Guardian Angel','A defensive alternative.']]];
function leagueBuilds(){const c=champions[state.champion],items=(state.champion==='yasuo'?swordSets:itemSets)[buildStage];return `${subnav('league','builds')}${pageHead('Your playbook','A plan before the play.','An illustrative loadout, with the thinking behind each step.',saveButton(state.savedLeague,'save-league','Save plan'))}<section class="build-layout"><aside class="build-portrait" style="--portrait-position:${state.champion==='yasuo'?'85%':'65%'};--champ-art:url('assets/${state.champion}.webp')"><div><p>${c.title}</p><h2>${c.name}</h2><span>${c.style}</span></div></aside><div class="build-content"><div class="build-subhead"><h2>${c.line}</h2><label>Champion<select id="build-champion" aria-label="Champion">${Object.entries(champions).map(([id,c])=>`<option value="${id}" ${state.champion===id?'selected':''}>${c.name}</option>`).join('')}</select></label></div><p class="muted">${c.tip}</p><div class="build-stages" aria-label="Purchase stage">${['Opening','Core direction','Adapt & finish'].map((n,i)=>`<button data-stage="${i}" aria-pressed="${buildStage===i}"><span>0${i+1}</span>${n}</button>`).join('')}</div><div class="item-trail">${items.map(([id,n,why],i)=>`<article><span class="item-order">${i+1}</span><img src="assets/item-${id}.png" alt=""><h3>${n}</h3><p>${why}</p></article>`).join('')}</div><div class="strategy-note"><span>◆</span><div><h3>${['Start with a purpose.','Build around your next fight.','Read the game in front of you.'][buildStage]}</h3><p>${['Think about the lane you want to play. Your starting purchase should support that approach.','Use this sequence to explore the loadout interface. In a real match, your recall and opponent change the order.','A plan should leave room for judgment. Your opponents and your team matter more than a fixed shopping list.'][buildStage]}</p></div></div><p class="sample-note">Example purchases for the design study. Not a current-patch recommendation.</p></div></section>`;}
function leagueHistory(id){const r=leagueMatches.find(m=>m.id===id);if(r)return `${subnav('league','history')}<div class="report-wrap">${link('#/league/history','All matches','back-link')}<section class="league-report" style="--champ-art:url('assets/${r.hero}.webp')"><p class="eyebrow">${r.date} / Sample match</p><span class="report-outcome ${r.result==='Victory'?'result-win':'result-loss'}">${r.result}</span><h1>${r.line}</h1><p>${champions[r.hero].name} · Mid · ${r.time}</p><div class="report-numbers"><div><strong>${r.kda}</strong><span>Kills / Deaths / Assists</span></div><div><strong>${r.cs}</strong><span>Minions</span></div><div><strong>${r.vision}</strong><span>Vision score</span></div></div></section><section class="quiet-note"><span>◇</span><div><h2>One thing to take forward.</h2><p>${r.note}</p>${link('#/league/builds/'+r.hero,'Revisit your plan','text-link')}</div></section></div>`;return `${subnav('league','history')}${pageHead('Your recent games','Every match leaves a lesson.','A few useful details. One thing to carry into the next game.')}<section class="history-layout"><div><div class="filter-row" aria-label="Match result">${['All','Victory','Defeat'].map(f=>`<button data-filter="${f}" aria-pressed="${historyFilter===f}">${f}</button>`).join('')}<small>3 sample matches</small></div><div class="match-list">${leagueMatches.filter(r=>historyFilter==='All'||r.result===historyFilter).map(r=>`<a class="league-match-row" href="#/league/history/${r.id}">${icon(r.hero)}<div><span class="${r.result==='Victory'?'result-win':'result-loss'}">${r.result}</span><h3>${champions[r.hero].name}</h3><small>${r.date}</small></div><strong>${r.kda}<small>K / D / A</small></strong><span>${r.time}</span><span class="row-arrow">↗</span></a>`).join('')}</div></div><aside class="history-aside"><span class="large-diamond">◇</span><p class="eyebrow">A useful habit</p><h2>Play.<br>Reflect.<br>Go again.</h2><p>Find one decision you would repeat—and one you would change.</p></aside></section>`;}
function boardMarkup(interactive=false){const positions=state.board||formations[state.plan].board;return `<div class="tactics-board ${interactive?'editable':''}" aria-label="Team positioning board">${Array.from({length:4},(_,r)=>`<div class="hex-row">${Array.from({length:7},(_,c)=>{const i=r*7+c,u=positions[i];return interactive?`<button class="hex ${u?'occupied':''} ${selectedCell===i?'picked':''}" data-cell="${i}" aria-label="Row ${r+1}, position ${c+1}${u?': '+units[u]:': empty'}" ${selectedCell===i?'aria-pressed="true"':''}>${u?icon(u):'<span>+</span>'}${u?`<small>${units[u]}</small>`:''}</button>`:`<div class="hex ${u?'occupied':''}">${u?icon(u):''}</div>`;}).join('')}</div>`).join('')}</div>`;}
function tftOverview(){return `${subnav('tft','')}<section class="tft-hero"><div class="tft-hero-art" aria-hidden="true"></div><div class="tft-copy"><p class="eyebrow">Welcome to the Convergence</p><h1>Small legends.<br>Big decisions.</h1><p>A clever little plan.<br>An unexpected combination.<br>Your next great board is out there.</p>${link('#/tft/comps','Find your next team')}<span class="tft-handnote">Make a little magic. ✧</span></div><div class="floating-token token-one" aria-hidden="true">✦</div><div class="floating-token token-two" aria-hidden="true">⬡</div></section><section class="tft-start"><article class="featured-board"><div><p class="eyebrow">From your strategy table</p><h2>${formations[state.plan].name}</h2><p>${formations[state.plan].tag}</p>${link('#/tft/planner','Open board planner','text-link')}</div>${boardMarkup()}</article><a class="tft-last" href="#/tft/history/t1"><span class="eyebrow">Last game / Sample</span><strong>1<sup>st</sup></strong><h3>A little planning.<br>A big finish.</h3><span>Revisit your final board ↗</span></a></section>`;}
function tftComps(){return `${subnav('tft','comps')}${pageHead('The strategy table','A team with a little chemistry.','Start with an idea. Make it your own.')}<section class="comp-collection">${formations.map((f,i)=>`<article class="comp-card comp-${i}"><div class="comp-art" style="background-image:url('assets/${f.carry}.webp')"><span class="comp-number">0${i+1}</span><span class="comp-style">${f.tag}</span></div><div class="comp-card-body"><h2>${f.name}</h2><p>${f.line}</p><div class="mini-roster">${Object.values(f.board).slice(0,5).map(u=>icon(u)).join('')}<span>+2</span></div><button class="action" data-plan="${i}">Explore this team <span>↗</span></button><small>${state.savedComps.includes(i)?'✓ Saved to your collection':'Example formation'}</small></div></article>`).join('')}</section><section class="quiet-note"><span>✧</span><div><h3>Good plans leave room for a pivot.</h3><p>These formations demonstrate the concept planner. They are not tied to a live TFT set or tier list.</p></div></section>`;}
function tftPlanner(){const f=formations[state.plan];return `${subnav('tft','planner')}${pageHead('Your team, your way',f.name,'A little preparation before the carousel starts.',saveButton(state.savedComps.includes(state.plan),'save-comp','Save team'))}<section class="planner-layout"><div class="board-table"><div class="board-toolbar"><label>Formation<select id="formation" aria-label="Formation">${formations.map((f,i)=>`<option value="${i}" ${state.plan===i?'selected':''}>${f.name}</option>`).join('')}</select></label><span><b>${Object.keys(state.board||f.board).length}</b> units on board</span><button class="text-button" data-action="reset-board">Reset board</button></div><div class="board-caption">FRONTLINE <span>◆</span> OPPONENT</div>${boardMarkup(true)}<div class="board-caption bottom">YOUR BACKLINE</div><div class="bench-label"><h3>Your bench</h3><span id="board-instruction" role="status">${selectedUnit?`Choose a hex for ${units[selectedUnit]}.`:selectedCell!==null?'Choose another hex to move or swap.':'Choose a unit, then a hex. Click a placed unit to move it.'}</span></div><div class="unit-bench">${Object.entries(units).map(([id,n])=>`<button data-unit="${id}" aria-pressed="${selectedUnit===id}">${icon(id)}<span>${n}</span></button>`).join('')}</div><button class="text-button remove-unit" data-action="remove-unit" ${selectedCell===null?'disabled':''}>Remove selected unit</button></div><aside class="planner-notes"><p class="eyebrow">The idea behind the board</p><h2>${f.line}</h2><p>${f.text}</p><ol>${f.stages.map((s,i)=>`<li><span>0${i+1}</span>${s}</li>`).join('')}</ol><div class="paper-tip"><span>✧</span><h3>One hex can change everything.</h3><p>Try swapping your carry to the other corner. A good plan adapts to what you see.</p></div><p class="sample-note">Illustrative roster. No live set, trait, or balance claims.</p></aside></section>`;}
function tftHistory(id){const r=tftMatches.find(m=>m.id===id);if(r){const f=formations[r.plan];return `${subnav('tft','history')}<section class="tft-report">${link('#/tft/history','All matches','back-link')}<div class="tft-report-title"><div><p class="eyebrow">${r.date} / Sample match</p><h1>${r.line}</h1><p>${f.name} · Final stage ${r.stage}</p></div><span class="placement-medal">${r.place}</span></div><div class="tft-recap"><div class="final-roster"><p class="eyebrow">Your final team</p><div>${Object.values(f.board).map(u=>`<span>${icon(u)}<b>${units[u]}</b></span>`).join('')}</div></div><article><h2>One decision to remember.</h2><p>${r.note}</p><button class="action" data-plan="${r.plan}">Revisit this formation <span>↗</span></button></article></div></section>`;}return `${subnav('tft','history')}${pageHead('Your recent games','A story in every finish.','Look past the placement. Find your next good decision.')}<section class="tft-history">${tftMatches.map(r=>`<a class="tft-match" href="#/tft/history/${r.id}"><span class="placement-medal ${r.place==='7th'?'low-place':''}">${r.place}</span><div><p>${r.date}</p><h2>${formations[r.plan].name}</h2><div class="mini-roster">${Object.values(formations[r.plan].board).slice(0,5).map(u=>icon(u)).join('')}</div></div><div class="tft-match-note"><p>${r.line}</p><span>Stage ${r.stage} <b>Review ↗</b></span></div></a>`).join('')}</section>`;}
function companion(){return `<section class="companion-page">${pageHead('Always in your corner','Go live a little.','One familiar companion, whichever game you’re playing.')}<div class="companion-layout"><div class="companion-orbit"><img src="assets/queuepop.svg" alt="QueuePop sigil"><span>${queueDemo?'Demo queue ready':'Ready when you are'}</span></div><div class="companion-controls"><h2>A quieter kind of teammate.</h2><p>Keep your plans close and step away between games. This concept explores the companion you already know.</p><div class="preference-row"><div><strong>Queue reminders</strong><p>Remember your preference in this concept.</p></div><button class="toggle" role="switch" aria-checked="${state.alerts}" data-action="toggle-alerts"><span></span><b>${state.alerts?'On':'Off'}</b></button></div><div class="demo-queue"><span class="eyebrow">Preview the ready state</span><h3>${queueDemo?'Your next game is ready.':'Try a queue-ready moment.'}</h3><p>${queueDemo?'This is a visual preview. No game client or notifications are connected.':'See how QueuePop brings you back when it is time to play.'}</p><button class="action" data-action="queue-demo">${queueDemo?'Reset preview':'Preview queue ready'}</button></div><p class="sample-note">Local concept only. Nothing is sent to your phone, Discord, or game client.</p></div></div></section>`;}
function render(focus=true){let [game='home',page='',id='']=location.hash.replace(/^#\/?/,'').split('/');if(!game)game='home';if(!['home','league','tft','companion'].includes(game))game='home';const valid=game==='league'?['','champions','builds','history']:['','comps','planner','history'];if(!valid.includes(page))page='';if(game==='league'&&page==='builds'&&champions[id]){state.champion=id;persist();}currentGame=game;currentPage=page;document.body.className=`theme-${game}`;renderQueuePopHeader(game);let html=game==='home'?home():game==='companion'?companion():game==='league'?(page==='champions'?leagueChampions():page==='builds'?leagueBuilds():page==='history'?leagueHistory(id):leagueOverview()):(page==='comps'?tftComps():page==='planner'?tftPlanner():page==='history'?tftHistory(id):tftOverview());$('#main').innerHTML=html;document.title=`${game==='home'?'Your games, together':game==='league'?'League of Legends':game==='tft'?'Teamfight Tactics':'Companion'} · QueuePop`;if(focus){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}}
function rerenderKeepingFocus(selector){const y=scrollY;render(false);if(selector)$(selector)?.focus({preventScroll:true});window.scrollTo(0,y);}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return;}const b=e.target.closest('button');if(!b)return;if(b.dataset.champion){state.champion=b.dataset.champion;persist();rerenderKeepingFocus(`[data-champion="${state.champion}"]`);}if(b.dataset.stage!==undefined){buildStage=+b.dataset.stage;rerenderKeepingFocus(`[data-stage="${buildStage}"]`);}if(b.dataset.filter){historyFilter=b.dataset.filter;rerenderKeepingFocus(`[data-filter="${historyFilter}"]`);}if(b.dataset.plan!==undefined){state.plan=+b.dataset.plan;state.board=state.boards[state.plan]||null;selectedCell=null;selectedUnit=null;persist();if(location.hash==='#/tft/planner')render();else location.hash='/tft/planner';}if(b.dataset.unit){selectedUnit=selectedUnit===b.dataset.unit?null:b.dataset.unit;selectedCell=null;rerenderKeepingFocus(`[data-unit="${b.dataset.unit}"]`);}if(b.dataset.cell!==undefined){const cell=+b.dataset.cell;state.board={...(state.board||formations[state.plan].board)};if(selectedUnit){for(const [i,u]of Object.entries(state.board))if(u===selectedUnit)delete state.board[i];state.board[cell]=selectedUnit;selectedUnit=null;toast('Unit placed.');}else if(selectedCell!==null){const unit=state.board[selectedCell];if(state.board[cell])state.board[selectedCell]=state.board[cell];else delete state.board[selectedCell];state.board[cell]=unit;selectedCell=null;toast('Position updated.');}else if(state.board[cell])selectedCell=cell;persist();rerenderKeepingFocus(`[data-cell="${cell}"]`);}const a=b.dataset.action;if(a==='save-league'){state.savedLeague=!state.savedLeague;persist();rerenderKeepingFocus('[data-action="save-league"]');toast(state.savedLeague?'Champion plan saved.':'Champion plan removed from saved.');}if(a==='save-comp'){const saved=state.savedComps.includes(state.plan);state.savedComps=saved?state.savedComps.filter(i=>i!==state.plan):[...state.savedComps,state.plan];persist();rerenderKeepingFocus('[data-action="save-comp"]');toast(saved?'Team removed from saved.':'Team saved. Your board is remembered locally.');}if(a==='reset-board'){state.board=null;selectedCell=null;selectedUnit=null;persist();rerenderKeepingFocus('[data-action="reset-board"]');toast('Original formation restored.');}if(a==='remove-unit'&&selectedCell!==null){state.board={...(state.board||formations[state.plan].board)};delete state.board[selectedCell];selectedCell=null;persist();rerenderKeepingFocus('[data-action="reset-board"]');toast('Unit returned to the bench.');}if(a==='toggle-alerts'){state.alerts=!state.alerts;persist();rerenderKeepingFocus('[data-action="toggle-alerts"]');}if(a==='queue-demo'){queueDemo=!queueDemo;rerenderKeepingFocus('[data-action="queue-demo"]');}});
document.addEventListener('change',e=>{if(e.target.id==='build-champion'){history.replaceState(null,'','#/league/builds');state.champion=e.target.value;persist();rerenderKeepingFocus('#build-champion');}if(e.target.id==='formation'){state.plan=+e.target.value;state.board=state.boards[state.plan]||null;selectedCell=null;selectedUnit=null;persist();rerenderKeepingFocus('#formation');}});
window.addEventListener('hashchange',()=>{historyFilter='All';selectedCell=null;selectedUnit=null;render();});
render(false);
